--- index.html
+++ index.html
@@ -36,9 +36,9 @@
 document.getElementById('attack').addEventListener('pointerdown',e=>{e.preventDefault();aim={x:1,y:0};shoot(p,1,0,false)});
 function aimPointer(e){const dx=e.clientX*scale-p.x,dy=e.clientY*scale-p.y;shoot(p,dx,dy,true)}
 function update(dt){if(state!='playing')return;accum+=dt;if(accum>.25){accum=0;time-=.25}if(time<=0)endMatch();p.cd-=dt;p.inv-=dt;
 let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+aim.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+aim.y,l=Math.hypot(mx,my)||1;if(l>1){mx/=l;my/=l}if(!stick&&Math.abs(mx+my)<.001&&l<=1){mx=keys.d||0-my}let nx=p.x+mx*p.speed*dt,ny=p.y+my*p.speed*dt;if(!wallHit(p,nx,p.y))p.x=nx;if(!wallHit(p,p.x,ny))p.y=ny;p.x=clamp(p.x,p.r,W-p.r);p.y=clamp(p.y,p.r,H-p.r);
-for(let i=gem.length-1;i>=0;i--){if(dist(p,gem[i])<p.r+gem[i].r){p.gems++;gem.splice(i,i,1)}}
+for(let i=gem.length-1;i>=0;i--){if(dist(p,gem[i])<p.r+gem[i].r){p.gems++;gem.splice(i,1)}}
 for(const b of bots){if(b.dead>0){b.respawn-=dt;if(b.respawn<=0){b.dead=0;b.hp=b.max;b.gems=b.team=='blue'?0:0;b.x=rnd(.15,.85)*W;b.y=rnd(.12,.35)*H}continue}b.inv-=dt;b.cd-=dt;
 let target=b.team=='red'?p:null;if(b.team=='blue')target=bots.find(q=>q.team=='red'&&q.dead<=0&&dist(q,b)<260*scale)||p;if(!target||target.dead>0)continue;if(b.team=='red'||b.team=='blue'){}
 let dx=(b.team=='red'?p.x:b.team=='blue'?findEnemy(b).x:p.x)-b.x,dy=(b.team=='red'?p.y:b.team=='blue'?findEnemy(b).y:p.y)-b.y,d=Math.hypot(dx,dy);if(d<240*scale&&b.cd<=0)shoot(b,dx,dy,false);let move=b.team=='red'?1:-1;if(d>150*scale&&b.team=='red'||d<100*scale&&b.team=='blue'){move=b.team=='red'?1:-1}else move=0;let nx=b.x+(dx/d)*b.speed*move*dt,ny=b.y+(dy/d)*b.speed*move*dt;if(!wallHit(b,nx,b.y))b.x=clamp(nx,b.r,W-b.r);if(!wallHit(b,b.x,ny))b.y=clamp(ny,b.r,H-b.r);
 if(dist(b,p)<b.r+p.r&&b.team=='red'&&p.inv<=0){hurt(p,8,b)}}
